    std::optional<BackgroundAgentStart> authorized_start;
    std::chrono::milliseconds bootstrap_timeout{5000},action_timeout{15000},request_timeout{250};
    // Explicit synthetic seam only. The worker checks an owned TEMP marker before invoking it.
    std::function<NativeHostConnection(NativeHostConnectOptions)> fixture_connector;
